// INPUT VALIDATION
// (IIE, 2026), (express-validator, 2026)

const { validationResult } = require('express-validator');

// Handles validation errors generated by express-validator and returns
// a controlled response when incoming request data does not meet the rules.
const handleValidationErrors = (req, res, next) => {
    // Collects all validation errors generated by the route's validation rules.
    const errors = validationResult(req);

    // Rejects invalid input before it reaches the route handler.
    // Returning the validation messages allows the client to identify which
    // supplied fields failed validation without exposing server-side details.
    if (!errors.isEmpty()) {
        return res.status(400).json({
            errors: errors.array()
        });
    }

    // Continue to the route handler when all validation rules have passed.
    next();
};

module.exports = handleValidationErrors;